CREATE TABLE `assessment_sessions` (
	`id` text PRIMARY KEY NOT NULL,
	`user_id` text NOT NULL,
	`version_id` text NOT NULL,
	`status` text DEFAULT 'in_progress' NOT NULL,
	`consent_policy_version` text NOT NULL,
	`started_at` integer NOT NULL,
	`submitted_at` integer,
	FOREIGN KEY (`version_id`) REFERENCES `assessment_versions`(`id`) ON UPDATE no action ON DELETE no action,
	CONSTRAINT "assessment_sessions_status_check" CHECK("assessment_sessions"."status" IN ('in_progress', 'submitted', 'scored')),
	CONSTRAINT "assessment_sessions_submitted_at_check" CHECK("assessment_sessions"."status" = 'in_progress' OR "assessment_sessions"."submitted_at" IS NOT NULL)
